type Resultado<T, E = string> =
  | { ok: true; valor: T }
  | { ok: false; erro: E };

function sucesso<T>(valor: T): Resultado<T, never> {
  return { ok: true, valor };
}

function falha<E>(erro: E): Resultado<never, E> {
  return { ok: false, erro };
}

function dividir(a: number, b: number): Resultado<number> {
  if (b === 0) {
    return falha("divisão por zero");
  }
  return sucesso(a / b);
}

const conta = dividir(10, 4);
if (conta.ok) {
  console.log(conta.valor.toFixed(2)); // "2.50"
} else {
  console.log(conta.erro.toUpperCase());
}

const partida = dividir(3, 0);
console.log(partida.ok); // false

// @ts-expect-error sem verificar o ok, o compilador só vê a união: valor pode não existir
console.log(partida.valor);

function agruparPor<T, C>(itens: readonly T[], chave: (item: T) => C): Map<C, T[]> {
  const grupos = new Map<C, T[]>();
  for (const item of itens) {
    const categoria = chave(item);
    const existente = grupos.get(categoria);
    if (existente === undefined) {
      grupos.set(categoria, [item]);
    } else {
      existente.push(item);
    }
  }
  return grupos;
}

type Livro = { titulo: string; genero: "ensaio" | "romance"; paginas: number };

const estante: Livro[] = [
  { titulo: "O Ano da Morte", genero: "romance", paginas: 336 },
  { titulo: "Ensaio sobre a Lucidez", genero: "romance", paginas: 328 },
  { titulo: "Discurso do Método", genero: "ensaio", paginas: 96 },
];

// C é inferido como "ensaio" | "romance": o Map fica Map<"ensaio" | "romance", Livro[]>
const porGenero = agruparPor(estante, (livro) => livro.genero);
console.log(porGenero.get("romance")?.length); // 2
console.log(porGenero.get("ensaio")?.[0]?.titulo); // "Discurso do Método"

// com outra função de chave, C passa a boolean sem mudar uma linha de agruparPor
const porTamanho = agruparPor(estante, (livro) => livro.paginas > 300);
console.log(porTamanho.get(false)?.length); // 1

// @ts-expect-error a chave do Map só aceita os géneros que a função devolveu
porGenero.get("poesia");

class CacheSimples<K, V> {
  private readonly entradas = new Map<K, V>();

  guardar(chave: K, valor: V): void {
    this.entradas.set(chave, valor);
  }

  obter(chave: K): V | undefined {
    return this.entradas.get(chave);
  }

  obterOuCalcular(chave: K, calcular: (chave: K) => V): V {
    const guardado = this.entradas.get(chave);
    if (guardado !== undefined) {
      return guardado;
    }
    const novo = calcular(chave);
    this.entradas.set(chave, novo);
    return novo;
  }

  get tamanho(): number {
    return this.entradas.size;
  }
}

const moradas = new CacheSimples<number, string>();
moradas.guardar(1, "Rua das Flores");
console.log(moradas.obter(1)?.toUpperCase()); // "RUA DAS FLORES"
console.log(moradas.obter(99)); // undefined
console.log(moradas.obterOuCalcular(2, (id) => `morada gerada ${id}`)); // "morada gerada 2"
console.log(moradas.tamanho); // 2

// com um objeto e assinatura de índice, o compilador promete um string que não está lá
const soltas: { [chave: string]: string } = { "1": "Rua das Flores" };
const inexistente = soltas["99"]; // tipado string, vale undefined
try {
  console.log(inexistente.toUpperCase());
} catch (erro) {
  console.log("rebentou em execução:", erro instanceof TypeError); // "rebentou em execução: true"
}

type Evento<TCarga> = { nome: string; instante: number; carga: TCarga };

function criarFabricaDeEventos<TCarga>(
  nome: string,
): (carga: TCarga, instante: number) => Evento<TCarga> {
  return (carga, instante) => ({ nome, instante, carga });
}

const criarLogin = criarFabricaDeEventos<{ utilizador: string }>("login");
const criarCompra = criarFabricaDeEventos<{ artigo: string; total: number }>("compra");

const entrada = criarLogin({ utilizador: "ana" }, 1000);
const compra = criarCompra({ artigo: "teclado", total: 49.9 }, 1200);

console.log(entrada.nome, entrada.carga.utilizador); // "login ana"
console.log(compra.carga.total.toFixed(2)); // "49.90"

// @ts-expect-error a fábrica já está especializada: esta carga não tem utilizador
criarLogin({ artigo: "teclado" }, 1300);

function comRegisto<TArgs extends unknown[], TRetorno>(
  etiqueta: string,
  fn: (...args: TArgs) => TRetorno,
): (...args: TArgs) => TRetorno {
  return (...args: TArgs): TRetorno => {
    console.log(`${etiqueta}: ${args.length} argumento(s)`);
    const resultado = fn(...args);
    console.log(`${etiqueta} devolveu ${String(resultado)}`);
    return resultado;
  };
}

function area(largura: number, altura: number): number {
  return largura * altura;
}

const areaComRegisto = comRegisto("area", area);

const total = areaComRegisto(3, 4);
