type Resultado<T, E = string> =
  | { ok: true; valor: T }
  | { ok: false; erro: E };

function sucesso<T>(valor: T): Resultado<T, never> {
  return { ok: true, valor };
}

function falha<E>(erro: E): Resultado<never, E> {
  return { ok: false, erro };
}

function analisarInteiro(texto: string): Resultado<number> {
  const numero = Number(texto);
  if (texto.trim() === "" || !Number.isInteger(numero)) {
    return falha(`"${texto}" não é um inteiro`);
  }
  return sucesso(numero);
}

function descrever(resultado: Resultado<number>): string {
  if (resultado.ok) {
    return `valor ${resultado.valor}`;
  }
  return `erro: ${resultado.erro}`;
}

console.log(descrever(analisarInteiro("42"))); // "valor 42"
console.log(descrever(analisarInteiro("4.2"))); // 'erro: "4.2" não é um inteiro'
console.log(descrever(analisarInteiro("   "))); // 'erro: "   " não é um inteiro'

function indexarPor<T, K>(itens: readonly T[], chave: (item: T) => K): Map<K, T> {
  const indice = new Map<K, T>();
  for (const item of itens) {
    indice.set(chave(item), item);
  }
  return indice;
}

