type Resultado<T, E = string> =
  | { ok: true; valor: T }
  | { ok: false; erro: E };

function sucesso<T>(valor: T): Resultado<T, never> {
  return { ok: true, valor };
}

function falha<E>(erro: E): Resultado<never, E> {
  return { ok: false, erro };
}

function recolher<T, E>(resultados: readonly Resultado<T, E>[]): Resultado<T[], E> {
  const valores: T[] = [];
  for (const resultado of resultados) {
    if (!resultado.ok) {
      return falha(resultado.erro);
    }
    valores.push(resultado.valor);
  }
  return sucesso(valores);
}

const todosBons: Resultado<number>[] = [sucesso(1), sucesso(2), sucesso(3)];
const comUmMau: Resultado<number>[] = [
  sucesso(1),
  falha("linha 2 inválida"),
  falha("linha 3 inválida"),
];

const bom = recolher(todosBons);
console.log(bom.ok ? bom.valor : bom.erro); // [ 1, 2, 3 ]

const mau = recolher(comUmMau);
console.log(mau.ok ? mau.valor : mau.erro); // "linha 2 inválida"

function memorizar<TArgs extends unknown[], TRetorno>(
  fn: (...args: TArgs) => TRetorno,
): { chamar: (...args: TArgs) => TRetorno; calculos: () => number } {
  const guardados = new Map<string, TRetorno>();
  let calculos = 0;

  return {
    chamar(...args: TArgs): TRetorno {
      const chave = JSON.stringify(args);
      const guardado = guardados.get(chave);
      if (guardado !== undefined) {
        return guardado;
      }
      calculos += 1;
      const novo = fn(...args);
      guardados.set(chave, novo);
      return novo;
    },
    calculos: () => calculos,
  };
}

function distancia(x: number, y: number): number {
  return Math.sqrt(x * x + y * y);
}

const memoria = memorizar(distancia);
console.log(memoria.chamar(3, 4)); // 5
console.log(memoria.chamar(3, 4)); // 5, sem voltar a calcular
console.log(memoria.chamar(6, 8)); // 10
console.log(memoria.calculos()); // 2

// @ts-expect-error o wrapper conserva a assinatura original: distancia precisa de dois números
memoria.chamar(3);
